<script setup>
import {ref} from 'vue'
const training=ref(false)
function curve(mixture){return Array.from({length:121},(_,i)=>{const x=(i-60)/17;const y=mixture ? .55*Math.exp(-.5*((x+1.4)/.65)**2)+.45*Math.exp(-.5*((x-1.4)/.55)**2) : Math.exp(-x*x/2);return `${15+i*2.7},${160-y*120}`}).join(' ')}
</script>
<template><div class="stack"><div class="tabs"><button :aria-pressed="training" @click.stop="training=true">Training · z → u</button><button :aria-pressed="!training" @click.stop="training=false">Inference · u → z</button></div><div class="flow grow"><div class="col"><h3>Retouching space z ∈ ℝ³</h3><svg viewBox="0 0 355 190" role="img" aria-label="Illustrative multimodal density, not measured model output"><line x1="15" y1="160" x2="340" y2="160" class="grid-lines"/><polyline :points="curve(true)" fill="none" stroke="var(--blue)" stroke-width="3"/><text x="170" y="187" text-anchor="middle" class="svg-label">Illustrative density slice</text></svg></div><div class="col" style="justify-content:center;align-items:center"><div class="node active" style="text-align:center"><h3>Conditional invertible f</h3><p>Condition c from image + history</p></div><p style="font-size:48px" aria-live="polite">{{training?'→':'←'}}</p><p class="formula">{{training?'u = f(z; c)':'z = f⁻¹(u; c)'}}</p></div><div class="col"><h3>Gaussian space u ∈ ℝ³</h3><svg viewBox="0 0 355 190" role="img" aria-label="Standard Gaussian density illustration"><line x1="15" y1="160" x2="340" y2="160" class="grid-lines"/><polyline :points="curve(false)" fill="none" stroke="var(--teal)" stroke-width="3"/><text x="170" y="187" text-anchor="middle" class="svg-label">u ∼ N(0, I)</text></svg></div></div><div class="sequence-emphasis"><p v-if="training" class="formula">log p(z | c) = log pₙ(f(z; c)) + log |det Jf|</p><p v-else class="formula">u₁, …, u₂₅₆ ∼ N(0, I) → z₁, …, z₂₅₆</p><p class="small">{{training?'Maximise conditional log-likelihood. The Jacobian accounts for changes in volume.':'Invert the flow for every sample, then select representative retouching candidates.'}}</p></div><p class="note">The density shapes above explain the mechanism; they are not fitted model evidence. A conditional flow can model complex densities, but multimodal preference validity requires additional data.</p></div></template>
